  <script>
document.addEventListener("DOMContentLoaded", function () {
  const popup = document.querySelector(".global-popup");
  const popupContainer = document.querySelector(".popup-container");
  const iframeFull = document.querySelector(".popup-iframe-full");
  const iframeGallery = document.querySelector(".popup-iframe-gallery");
  /* EVENT DELEGATION (works after pagination) */
  document.addEventListener("click", function(e){
    const item = e.target.closest(".work-cms-item");
    if(!item) return;
    e.preventDefault();
    e.stopPropagation();
    let pageUrl = item.dataset.pageUrl;
    let slug = item.dataset.slug;
    console.log("pageUrl:", pageUrl);
    console.log("slug:", slug);
    popup.classList.add("active");
    if(pageUrl && pageUrl.trim() !== ""){
      /* FULL CONTENT MODE */
      popupContainer.classList.remove("gallery-mode");
      iframeFull.style.display = "block";
      iframeGallery.style.display = "none";
      iframeFull.src = pageUrl;
    } else {
      /* GALLERY MODE */
      popupContainer.classList.add("gallery-mode");
      iframeFull.style.display = "none";
      iframeGallery.style.display = "block";
      iframeGallery.src = "/our-work/" + slug;
    }
  });
  /* CLOSE POPUP */
  document.querySelector(".popup-close").addEventListener("click", function(){
    popup.classList.remove("active");
    popupContainer.classList.remove("gallery-mode");
    iframeFull.src = "";
    iframeGallery.src = "";
  });
});
</script>
