#### **Pagination Logic**

```javascript
document.addEventListener('DOMContentLoaded', function () {
  const itemsPerPage = 8;
  const wrapper = document.getElementById('cms-wrapper');
  let currentPage = 1;
  let activeItems = [];
  let isOurUpdate = false;

  function getNav() {
    let nav = document.getElementById('custom-pagination');
    if (!nav) {
      nav = document.createElement('div');
      nav.id = 'custom-pagination';
      nav.style.cssText = 'display:flex;align-items:center;justify-content:center;gap:8px;margin-top:40px;';
      wrapper.parentNode.insertBefore(nav, wrapper.nextSibling);
    }
    return nav;
  }

  function getFinsweetVisibleItems() {
    const all = [...wrapper.querySelectorAll('.work-cms-item')];
    all.forEach(item => {
      if (item.style.getPropertyPriority('display') === 'important') {
        item.style.removeProperty('display');
      }
    });
    return all.filter(item => window.getComputedStyle(item).display !== 'none');
  }

  function applyPage(page, items) {
    const start = (page - 1) * itemsPerPage;
    items.forEach((item, i) => {
      if (i >= start && i < start + itemsPerPage) {
        item.style.removeProperty('display');
      } else {
        item.style.setProperty('display', 'none', 'important');
      }
    });
  }

  function showPage(page) {
    currentPage = page;
    isOurUpdate = true;
    applyPage(page, activeItems);

    setTimeout(() => {
      applyPage(page, activeItems);
      isOurUpdate = false;
    }, 50);

    setTimeout(() => {
      applyPage(page, activeItems);
    }, 200);

    renderPagination();
    wrapper.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  function renderPagination() {
    const nav = getNav();
    nav.innerHTML = '';
    const totalPages = Math.ceil(activeItems.length / itemsPerPage);

    if (totalPages <= 1) {
      nav.style.display = 'none';
      return;
    }

    nav.style.display = 'flex';

    const makeBtn = (label, targetPage, isActive, isDisabled) => {
      const b = document.createElement('button');
      b.textContent = label;
      b.style.cssText = `
        width:44px;height:44px;border-radius:12px;border:none;cursor:pointer;
        font-size:15px;font-weight:600;font-family:inherit;
        background:${isActive ? '#1a3a6e' : 'white'};
        color:${isActive ? 'white' : '#1a3a6e'};
        box-shadow:0 2px 8px rgba(0,0,0,0.08);
        opacity:${isDisabled ? '0.4' : '1'};
        pointer-events:${isDisabled ? 'none' : 'auto'};
        transition:all 0.15s;
      `;
      if (!isActive && !isDisabled) {
        b.addEventListener('click', () => showPage(targetPage));
      }
      return b;
    };

    nav.appendChild(makeBtn('<<', currentPage - 1, false, currentPage === 1));
    for (let i = 1; i <= totalPages; i++) {
      nav.appendChild(makeBtn(i, i, i === currentPage, false));
    }
    nav.appendChild(makeBtn('>>', currentPage + 1, false, currentPage === totalPages));
  }

  function rebuildPagination() {
    if (isOurUpdate) return;
    activeItems = getFinsweetVisibleItems();
    currentPage = 1;
    showPage(1);
  }

  let debounce;
  const observer = new MutationObserver(() => {
    if (isOurUpdate) return;
    clearTimeout(debounce);
    debounce = setTimeout(rebuildPagination, 300);
  });

  setTimeout(() => {
    rebuildPagination();
    observer.observe(wrapper, {
      attributes: true,
      subtree: true,
      attributeFilter: ['class', 'style']
    });

    document.querySelectorAll('input[fs-list-field]').forEach(cb => {
      cb.addEventListener('change', () => {
        setTimeout(rebuildPagination, 500);
      });
    });

    document.querySelectorAll('[fs-list-element="clear"]').forEach(btn => {
      btn.addEventListener('click', () => {
        setTimeout(rebuildPagination, 500);
      });
    });
  }, 1200);
});
```

